do $$begin if current_database()<>'aimade_apk_qa' then raise exception 'Local APK QA only';end if;end$$;
begin;
create function public.qa_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is not true then raise exception 'FAILED: %',label;end if;raise notice 'PASS: %',label;end$$;
create function public.qa_denied(command text) returns boolean language plpgsql as $$begin execute command;return false;exception when others then return true;end$$;
grant execute on function public.qa_assert(boolean,text),public.qa_denied(text) to anon,authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select qa_assert(qa_denied($x$select reserve_apk_upload('00000000-0000-4000-8000-000000000020',26214401,'test.apk',repeat('a',64))$x$),'reject oversize');
select qa_assert(qa_denied($x$select reserve_apk_upload('00000000-0000-4000-8000-000000000020',128,'../test.apk',repeat('a',64))$x$),'reject path traversal');
select id as apk_id,object_path as apk_path from reserve_apk_upload('00000000-0000-4000-8000-000000000020',128,'test.apk',repeat('a',64)) \gset
select qa_assert((select count(*)=1 from apk_uploads),'owner sees reservation');
select qa_assert(qa_denied(format('select review_apk_upload(%L,true,%L,%L)',:'apk_id',repeat('x',30),repeat('a',64))),'member cannot approve');
select qa_assert(qa_denied(format('select finish_apk_upload(%L)',:'apk_id')),'cannot finalize missing object');
select qa_assert(qa_denied($x$insert into storage.objects(bucket_id,name) values('apk-quarantine','unknown.apk')$x$),'unreserved upload denied');
insert into storage.objects(bucket_id,name,metadata) values('apk-quarantine',:'apk_path','{"size":128}');
select qa_assert((select count(*)=0 from storage.objects),'author cannot read or sign unreviewed objects');
select finish_apk_upload(:'apk_id');
select qa_assert((select status='pending' from apk_uploads where id=:'apk_id'),'finalize is pending, not public');
select qa_assert((select count(*)=0 from public_apk_for_work('00000000-0000-4000-8000-000000000020')),'pending absent from public metadata');
select qa_assert(qa_denied($x$update apk_uploads set status='approved'$x$),'direct status writes denied');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select qa_assert((select count(*)=0 from apk_uploads),'other member sees no private metadata');
select qa_assert(qa_denied($x$select reserve_apk_upload('00000000-0000-4000-8000-000000000020',128,'test.apk',repeat('a',64))$x$),'unverified member denied');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select qa_assert(qa_denied($x$select reserve_apk_upload('00000000-0000-4000-8000-000000000020',128,'test.apk',repeat('a',64))$x$),'admin cannot replace another author file');
select qa_assert((select count(*)=1 from storage.objects),'admin can inspect quarantine');
select qa_assert(qa_denied(format('select review_apk_upload(%L,true,%L,%L)',:'apk_id',repeat('x',30),repeat('b',64))),'approval hash must match');
select qa_assert(qa_denied(format('select review_apk_upload(%L,true,%L,%L)',:'apk_id','checked',repeat('a',64))),'review record required');
select review_apk_upload(:'apk_id',true,'Synthetic review only: source and scanner record checked.',repeat('a',64));
select qa_assert((select count(*)=1 from public_apk_for_work('00000000-0000-4000-8000-000000000020')),'approved public metadata available');
with changed as(update storage.objects set metadata='{"size":256}' returning *) select qa_assert((select count(*)=0 from changed),'even admin cannot replace reviewed object');
with changed as(delete from storage.objects returning *) select qa_assert((select count(*)=0 from changed),'cannot delete objects to evade quota');
update works set archived=true,moderation_status='hidden' where id='00000000-0000-4000-8000-000000000020';
select qa_assert((select count(*)=0 from public_apk_for_work('00000000-0000-4000-8000-000000000020')),'unpublished work immediately leaves download listing');
update works set archived=false,moderation_status='clear' where id='00000000-0000-4000-8000-000000000020';
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select qa_assert((select count(*)=0 from storage.objects),'anonymous cannot read / sign even approved object');
select qa_assert(qa_denied('select * from apk_uploads'),'private review notes denied to anonymous');
select qa_assert((select count(*)=1 from public_apk_for_work('00000000-0000-4000-8000-000000000020')),'only public projection is anonymous');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select withdraw_apk_upload(:'apk_id');
select qa_assert((select count(*)=0 from public_apk_for_work('00000000-0000-4000-8000-000000000020')),'author withdrawal removes download');
select id from reserve_apk_upload('00000000-0000-4000-8000-000000000020',128,'second.apk',repeat('b',64));
select qa_assert(qa_denied($x$select reserve_apk_upload('00000000-0000-4000-8000-000000000020',128,'third.apk',repeat('c',64))$x$),'two reservations per day enforced after withdrawal');
update works set details='{"platforms":["ios","android"],"beta":true,"appStore":"https://apps.apple.com/app/id123","googlePlay":"https://play.google.com/store/apps/details?id=com.example.app"}' where id='00000000-0000-4000-8000-000000000020';
select qa_assert(qa_denied($x$update works set details='{"appStore":"https://apps.apple.com.evil.test/app/id123"}'$x$),'database rejects lookalike stores');
select qa_assert(qa_denied($x$update works set details='{"platforms":["evil"]}'$x$),'database rejects unknown platform');
select qa_assert(qa_denied($x$update works set details='{"beta":"true"}'$x$),'database rejects string beta');
rollback;
